$root = (Get-Location).Path
$out = Join-Path $root 'transcriptions'
if (-not (Test-Path -LiteralPath $out)) { New-Item -ItemType Directory -Path $out | Out-Null }
foreach ($zip in @(Get-ChildItem -File -Filter *.zip)) {
    $name = $zip.BaseName
    $dest = Join-Path $root $name
    try {
        $ErrorActionPreference = 'Stop'
        if (-not (Test-Path -LiteralPath $dest)) { New-Item -ItemType Directory -Path $dest | Out-Null }
        Expand-Archive -LiteralPath $zip.FullName -DestinationPath $dest -Force
        Remove-Item -LiteralPath $zip.FullName -Force
        Write-Host "UNZIP $name"
    } catch {
        Write-Host "FAIL  $name -> $($_.Exception.Message)" -ForegroundColor Red
    }
}
foreach ($dir in @(Get-ChildItem -Directory | Where-Object { $_.FullName -ne $out })) {
    $name = $dir.Name
    try {
        $ErrorActionPreference = 'Stop'
        $txt = Get-ChildItem -LiteralPath $dir.FullName -Recurse -File -Filter transcription.txt |
            Select-Object -First 1
        if ($txt) {
            Copy-Item -LiteralPath $txt.FullName -Destination (Join-Path $out ($name + '.txt')) -Force
            Write-Host "OK    $name"
        } else {
            Write-Host "SKIP  $name -> no transcription.txt"
        }
    } catch {
        Write-Host "FAIL  $name -> $($_.Exception.Message)" -ForegroundColor Red
    }
}
